using System.Windows;using System.Windows.Controls;using Crown___Sovereign.Data;using Crown___Sovereign.Services;namespace Crown___Sovereign.Views.UserControls.Administracion.Configuracion;public partial class ConfiguracionHotelControl:UserControl{public ConfiguracionHotelControl(){InitializeComponent();NameBox.Text=SampleData.ConfiguracionHotel["Nombre"];CategoryBox.Text=SampleData.ConfiguracionHotel["Categoría"];AddressBox.Text=SampleData.ConfiguracionHotel["Dirección"];PhoneBox.Text=SampleData.ConfiguracionHotel["Teléfono"];EmailBox.Text=SampleData.ConfiguracionHotel["Correo"];}private void Save_Click(object s,RoutedEventArgs e){var service=new AdministracionService();service.GuardarConfiguracion("Nombre",NameBox.Text);service.GuardarConfiguracion("Categoría",CategoryBox.Text);service.GuardarConfiguracion("Dirección",AddressBox.Text);service.GuardarConfiguracion("Teléfono",PhoneBox.Text);service.GuardarConfiguracion("Correo",EmailBox.Text);StatusText.Text="Configuración guardada.";}}
